def limpiar_emails_duplicados(apps, schema_editor):
    """Limpia emails duplicados manteniendo el usuario más reciente"""
    Usuario = apps.get_model('usuarios', 'Usuario')
    
    # Encontrar emails duplicados
    emails_duplicados = Usuario.objects.values('email').annotate(
        count=Count('email')
    ).filter(count__gt=1)
    
    for item in emails_duplicados:
        email = item['email']
        if email:  # Solo procesar emails no vacíos
            # Obtener todos los usuarios con este email
            usuarios_duplicados = Usuario.objects.filter(email=email).order_by('-date_joined')
            
            # Mantener el más reciente, eliminar o modificar los demás
            for i, usuario in enumerate(usuarios_duplicados):
                if i > 0:  # No es el más reciente
                    # Cambiar el email para evitar duplicados
                    usuario.email = f"{email}_duplicado_{usuario.id}"
                    usuario.save()

